"""Shared viewer inside Daylight against frozen projections; no model/browser actions."""
import hashlib,json,os,subprocess
from pathlib import Path
from uuid import uuid4
from playwright.sync_api import sync_playwright,expect
ROOT=Path(__file__).resolve().parents[1]
def main():
 os.environ['LD_LIBRARY_PATH']=str(ROOT/'.local/system-libs/usr/lib/x86_64-linux-gnu')+':'+os.environ.get('LD_LIBRARY_PATH','')
 out=ROOT/'.local/vercel-demo'/('shared-viewer-'+uuid4().hex[:8]);out.mkdir(parents=True)
 process=subprocess.Popen(['node','tests/library-server.mjs'],cwd=ROOT/'deploy/daylight',stdout=subprocess.PIPE,text=True)
 info=json.loads(process.stdout.readline());origin='http://127.0.0.1:'+str(info['port']);checks=[]
 def check(name,value):
  assert value,name
  checks.append(name);print('PASS',name,flush=True)
 try:
  with sync_playwright() as p:
   browser=p.chromium.launch();context=browser.new_context(viewport={'width':1512,'height':1040});page=context.new_page();errors=[];writes=[]
   page.on('pageerror',lambda e:errors.append(str(e)));page.on('request',lambda r:writes.append(r.url) if r.method=='POST' else None)
   check('Local fixture requires invitation for viewer and projection',page.request.get(origin+'/trace-viewer').status==401 and page.request.get(origin+'/api/library/sessions').status==401)
   page.goto(origin+'/workspace/replays');page.get_by_label('Your invitation code').fill('offline-library-code-'*3);page.get_by_role('button',name='Open demo').click();page.locator('#all-replays-link').click();writes.clear()
   rows=page.locator('#global-rows tr[data-run^="l:"]');expect(rows).to_have_count(1)
   stats=page.request.get(origin+'/__fixture/stats').json()
   check('Library listing reads summaries without full session or media',stats['sessions']==0 and stats['assets']==0)
   check('Historical interaction kind stays unknown and exact failed grade is retained',rows.first.get_attribute('data-kind')=='unknown' and 'Failed' in rows.first.inner_text())
   page.locator('#global-library-more').click();expect(rows).to_have_count(2)
   check('Explicit load-more follows opaque cursor without duplicate entries',page.request.get(origin+'/__fixture/stats').json()['catalog']==2)
   page.route('**/api/library/sessions',lambda route:route.fulfill(status=503,json={'error':'Review fixture disconnected'}),times=1)
   page.locator('#global-library-more').click();expect(page.locator('#global-library-more')).to_have_text('Retry saved library');expect(rows).to_have_count(2)
   check('Catalog failure preserves loaded runs and offers explicit retry',True)
   page.locator('#global-library-more').click();expect(page.locator('#global-library-more')).to_have_text('Load more saved runs');expect(rows).to_have_count(1)
   page.locator('#global-library-more').click();expect(rows).to_have_count(2)
   page.locator('#global-site').select_option('tricky-health');expect(rows).to_have_count(1);rows.locator('.run-title').click()
   viewer=page.frame_locator('#shared-trace-viewer');expect(viewer.locator('#chat .bubble')).not_to_have_count(0)
   check('Shared readable viewer is embedded inside existing site layout',page.locator('.site-rail').is_visible() and viewer.locator('body').evaluate('el=>el.classList.contains("viewer-embedded")') and viewer.locator('.json-toolbar').count()>0)
   check('Opening one saved run reads one projection only',page.request.get(origin+'/__fixture/stats').json()['sessions']==1)
   check('Collapsed screenshots load on demand',page.request.get(origin+'/__fixture/stats').json()['assets']==0)
   page.screenshot(path=str(out/'conversation-desktop.png'),full_page=True)
   viewer.get_by_role('button',name='Tools only',exact=True).click();expect(viewer.locator('.trace-tool-event')).to_have_count(12)
   check('All twelve BrowserGym tool events form the chronological timeline',viewer.locator('.trace-tool-number').all_text_contents()==[str(i) for i in range(1,13)])
   viewer.locator('.trace-toolbox>summary').click();check('Old unstructured tool definitions remain unknown','not present' in viewer.locator('.trace-tool-inventory').inner_text())
   viewer.get_by_role('button',name='Replay',exact=True).click();expect(viewer.locator('.browser-replay')).to_be_visible()
   expect(viewer.locator('.browser-replay-stage img')).to_be_visible();expect(viewer.locator('.browser-replay-stage img')).to_have_js_property('complete',True)
   before=viewer.locator('.browser-replay-stage img').get_attribute('src');viewer.get_by_role('button',name='Next →',exact=True).click();expect(viewer.locator('.browser-replay [role=status]')).to_contain_text('Step 1')
   check('Recorded replay advances to the next exact screenshot',viewer.locator('.browser-replay-stage img').get_attribute('src')!=before)
   check('Replay and available-tool step selection stay synchronized',viewer.locator('.trace-tool-decision').input_value().endswith(':1'))
   phases=viewer.locator('.browser-replay-controls select').last.locator('option').all_text_contents()
   check('Transition feedback is visibly separate from decision observation',any('separate from decision' in value for value in phases) and 'Decision observation' in phases)
   viewer.locator('.browser-replay-controls select').last.select_option(label='Transition · separate from decision input')
   transition=viewer.locator('.browser-replay details pre').text_content();viewer.locator('.browser-replay-controls select').last.select_option(label='Decision observation')
   check('Replay phase selection preserves actual observation text',transition and viewer.locator('.browser-replay details pre').text_content())
   page.wait_for_function("parseFloat(document.querySelector('#shared-trace-viewer').style.height)<4000")
   check('Embedded frame shrinks after switching away from long message view',page.locator('#shared-trace-viewer').bounding_box()['height']<4000)
   page.screenshot(path=str(out/'replay-desktop.png'),full_page=True)
   viewer.get_by_role('button',name='Play steps',exact=True).click();expect(viewer.get_by_role('button',name='Pause',exact=True)).to_be_visible();viewer.get_by_role('button',name='Pause',exact=True).click()
   check('Recorded slideshow offers explicit pause without executing actions',not writes)
   viewer.get_by_role('button',name='Inspect this step’s messages',exact=True).click();expect(viewer.locator('#chat')).to_be_visible();expect(viewer.locator('.browser-replay')).to_be_hidden()
   viewer.locator('#search').fill('Privileged verifier');expect(viewer.locator('#chat')).to_contain_text('Privileged verifier');check('Shared search includes privileged evaluation with its original label',viewer.locator('#chat').inner_text().lower().find('not model input')>=0)
   page.set_viewport_size({'width':390,'height':844});viewer.get_by_role('button',name='Replay',exact=True).click()
   check('Workspace and embedded viewer fit mobile width',page.evaluate('document.documentElement.scrollWidth<=innerWidth') and viewer.locator('html').evaluate('e=>e.scrollWidth<=innerWidth'))
   page.screenshot(path=str(out/'replay-mobile.png'),full_page=True)
   page.locator('#all-replays-link').click();expect(page.locator('#shared-trace-viewer')).not_to_have_attribute('src',__import__('re').compile('.+'))
   check('Leaving replay unloads the iframe and stops playback',not page.locator('#shared-trace-viewer').get_attribute('src'))
   page.locator('#clear-filters').click();page.locator('#global-grade').select_option('unknown');expect(rows).to_have_count(1);rows.locator('.run-title').click();expect(viewer.locator('#chat .bubble')).not_to_have_count(0)
   viewer.get_by_role('button',name='Tools only',exact=True).click();check('Parser-failure run keeps unknown grade and empty tool timeline',page.locator('#review-grade').inner_text()=='Unknown' and 'No tool calls' in viewer.locator('.trace-tool-timeline').inner_text())
   deep=context.new_page();deep.goto(origin+'/workspace/replays?run=l:'+info['sessions'][0]);expect(deep.frame_locator('#shared-trace-viewer').locator('#chat .bubble')).not_to_have_count(0)
   check('Saved-session deep link restores viewer and explicit publication metadata',deep.locator('#review-kind').inner_text().lower().find('health account')>=0 and deep.locator('#review-grade').inner_text()=='Failed');deep.close()
   before_reads=page.request.get(origin+'/__fixture/stats').json()['catalog'];page.evaluate('document.dispatchEvent(new Event("visibilitychange"))')
   page.wait_for_timeout(250)
   check('Returning to the page does not poll saved-session catalog',page.request.get(origin+'/__fixture/stats').json()['catalog']==before_reads)
   standalone=context.new_page();standalone.goto(origin+'/trace-viewer#'+info['sessions'][0]);expect(standalone.locator('.trace-tools-panel')).to_be_visible();standalone.get_by_role('button',name='Replay',exact=True).click()
   standalone.evaluate('location.hash="missing-session"');expect(standalone.locator('#title')).to_have_text('Session not found');expect(standalone.locator('.browser-replay')).to_be_hidden()
   check('Missing standalone session clears previous replay and tool controls',standalone.locator('.trace-tools-panel').count()==0);standalone.close()
   private=browser.new_context();foreign=private.new_page();foreign.goto(origin);foreign.get_by_label('Your invitation code').fill('offline-foreign-code-'*3);foreign.get_by_role('button',name='Open demo').click()
   check('Foreign fixture owner cannot read another session',foreign.request.get(origin+'/api/library/sessions/'+info['sessions'][0]).status==404 and foreign.request.get(origin+'/api/library/sessions').json()['sessions']==[])
   check('Saved browsing makes no job/model writes',not writes and page.request.get(origin+'/__fixture/stats').json()['writes']==0);check('No browser JavaScript errors',not errors)
   browser.close()
  (out/'report.json').write_text(json.dumps({'passed':True,'checks':checks,'paid_calls':0,'runtime':'Fixture library endpoints around actual invitation handler; production backend integration pending','sources':{n:hashlib.sha256((ROOT/'deploy/daylight'/n).read_bytes()).hexdigest() for n in ['prepare-viewer.mjs','client/trace-browser.js','client/trace-browser.css','client/workspace.js','client/workspace.html']}},indent=2));print(json.dumps({'checks':len(checks),'report':str(out/'report.json')}))
 finally:process.terminate();process.wait(timeout=10)
if __name__=='__main__':main()
